import{d as g,C as t,o as c,c as u,j as a,a as n,E as o,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二十六章","description":"从重轻、静躁与辎重之喻，理解行事中的根本和承担。","frontmatter":{"title":"道德经第二十六章","description":"从重轻、静躁与辎重之喻，理解行事中的根本和承担。","category":"guide","aliases":["道德经第二十六章","老子第二十六章","dao de jing chapter 26"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-26.md","filePath":"daoism/dao-de-jing/chapter-26.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-26.md"},y=g({...m,setup(b){const s=[{id:"weight-and-stillness",label:"重为轻根，静为躁君",showLabel:!0,sentences:[[{text:"重",glossary:"zhong"},"为轻根，",{text:"静",glossary:"jing"},"为",{text:"躁",glossary:"zao"},{text:"君",glossary:"jun"},"。"]],note:["【白话】厚重是轻浮所凭依的根，安静是躁动的主导。这两句把承载与主导放在前面，说明轻动不能脱离所依的根本。","【王弼注择要】「凡物轻不能载重，小不能镇大。」注又说「不行者使行，不动者制动」，以能承载、能统摄解释重与静的地位。","【读法】重先与轻相对，静先与躁相对；这里不是物理重量的普遍定律。君借主导者为喻，与末尾失君的君位义须随句分辨。"]},{id:"travel-with-provisions",label:"是以圣人终日行，不离辎重",showLabel:!0,sentences:[["是以圣人终日行，不离",{text:"辎重",glossary:"zizhong"},"。"]],note:["【白话】因此圣人即使整天行走，也不离开行旅所需的载重车辆与物资。借这幅行路之象，说明行动时仍有所依，不使根本落空。","【王弼注择要】「以重为本，故不离。」注直接把辎重连到前文的重为轻根，不把行走与守本说成互相排斥。","【读法】辎重原为出行、行军所载的衣粮器具及车辆；本章借物资与行程的关系说根本。不能只把重解作心理上的严肃，遗漏实际承载。"]},{id:"splendour-without-entanglement",label:"虽有荣观，燕处超然",showLabel:!0,sentences:[["虽有",{text:"荣观",glossary:"rongguan"},"，",{text:"燕处",glossary:"yanchu"},{text:"超然",glossary:"chaoran"},"。"]],note:["【白话】即使有华美的景观或盛大的陈设，仍能安然居处，超然不为之牵动。这承接不离辎重，写外在繁华不致夺去所守。","【王弼注择要】「不以经心也。」王弼用不使荣观萦绕于心解释燕处超然，着眼于心不被外物牵走。","【读法】观在景观义读 guàn，燕取安义。超然不等于对眼前职责毫不关心，而是安处、不以华美扰动本心的样态。"]},{id:"ruler-and-responsibility",label:"轻则失根，躁则失君",showLabel:!0,sentences:[["奈何",{text:"万乘",glossary:"wansheng"},"之主，而以身轻天下？轻则失根，躁则失",{text:"君",glossary:"jun-position"},"。"]],note:["【白话】身为大国之主，怎么能以自身轻率地对待天下呢？轻率便失去根本，躁动便失去主位。末尾将守本的要求落到承担天下之责的人身上。","【王弼注择要】「失本为丧身也，失君为失君位也。」所据录文正文作失本；王弼由失本连到自身的危失，由失君连到君位。","【读法】本站保留失根，读义与失本相参；以身轻天下有不同讲法，本页取人主轻率处天下来读。君位是古代政治语境，不把末句全改成现代情绪管理术。"]}],r=[{id:"zhong",term:"重",sense:1},{id:"jing",term:"静",sense:1},{id:"zao",term:"躁",sense:1},{id:"jun",term:"君",sense:1},{id:"jun-position",term:"君",sense:2},{id:"zizhong",term:"辎重",sense:1},{id:"rongguan",term:"荣观",sense:1},{id:"yanchu",term:"燕处",sense:1},{id:"chaoran",term:"超然",sense:1},{id:"wansheng",term:"万乘",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十六章",tabindex:"-1"},[n("道德经第二十六章 "),a("a",{class:"header-anchor",href:"#道德经第二十六章","aria-label":'Permalink to "道德经第二十六章"'},"​")],-1)),o(i,{title:"终日行走，怎样仍不离开根本",summary:"重与静先被说成轻与躁的根本、主导；行路不离辎重、面对荣观仍安处，再转为对万乘之主的告诫。",points:[{label:"先读",text:"分清重轻、静躁的关系，重在何者承载、何者主导。"},{label:"再辨",text:"辎重先按行旅物资读，再看它如何成为不离根本的比喻。"},{label:"后看",text:"末尾回到人主与天下，轻躁的代价涉及自身与职分。"}],hint:"重读 zhòng，荣观的观读 guàn，万乘的乘读 shèng；本站失根与录文失本的差异见篇末。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:s,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"重为轻根，静为躁君。",tone:"承载与主导",guide:"轻动要有承载，行动要有主导；从两种关系理解重静，不把静等同停止行动。"},{text:"是以圣人终日行，不离辎重。",tone:"行与守本",guide:"终日行与不离并存，提醒根本应当落实为行动所需的支撑。"},{text:"轻则失根，躁则失君。",tone:"轻躁的代价",guide:"回到人主的职分看此句，也可由此检查行动是否已失去所依与所守。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-既然重静为本-为什么还要终日行" tabindex="-1">象：既然重静为本，为什么还要终日行？ <a class="header-anchor" href="#象-既然重静为本-为什么还要终日行" aria-label="Permalink to &quot;象：既然重静为本，为什么还要终日行？&quot;">​</a></h3><p>本章并未把理想放在原地不动，而是写整日行走仍不离辎重。静与重为行提供稳定的主导和承载，二者使行动可以持续，不必取消行动。</p><h3 id="理-荣观为什么会成为问题" tabindex="-1">理：荣观为什么会成为问题？ <a class="header-anchor" href="#理-荣观为什么会成为问题" aria-label="Permalink to &quot;理：荣观为什么会成为问题？&quot;">​</a></h3><p>华美本身不是全章唯一的批评对象，关键在是否让它牵走心志、使所守落空。王弼以不以经心解释，显示根本与外在所见的次序。</p><h3 id="用-今天怎样找到自己的辎重" tabindex="-1">用：今天怎样找到自己的辎重？ <a class="header-anchor" href="#用-今天怎样找到自己的辎重" aria-label="Permalink to &quot;用：今天怎样找到自己的辎重？&quot;">​</a></h3><p>可以具体检查睡眠、生活条件、可靠资料、协作约定与必要资源，哪些正在承载自己的行动。再忙也不长期透支这些条件，才让守本不止于一句提醒。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先补承载，再加行程。</strong> 决定承担更多工作时，先确认时间、资源与恢复条件是否足够。根本也可能是很具体的物资、技能和可靠关系。</p><p><strong>让重要判断有安静的位置。</strong> 面对声势、奖励或紧迫感，保留核对事实与责任的时间。安静有助于主导行动，仍须落实为及时而清楚的决策。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我正在加快的这段行程，由什么承载？如果继续加码，最先被抛下的根本是什么？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「轻则失根」；HFL 录文作「轻则失本」，王弼注文也连「失本」申说，本页明记差异。</li><li>辎重读 zī zhòng，荣观读 róng guàn，万乘读 wàn shèng；君的主导者与君位两义分开绑定。</li><li>「以身轻天下」本页取人主轻率处天下的读法，不将有争议的句义写成唯一解释。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，005a–005b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
